47	{
48	    size_t operator()(const IKey *k1, const IKey *k2) const
49	    {
50	        NVCV_ASSERT(k1 != nullptr);
51	        NVCV_ASSERT(k2 != nullptr);
52	        return *k1 == *k2;
53	    }
