56	CacheItem::CacheItem()
57	{
58	    static std::atomic_uint16_t idnext = 0;
59	
60	    m_id = idnext++;
61	}
62	
63	uint64_t CacheItem::id() const
64	{
65	    return m_id;
66	}
67	
68	std::shared_ptr<CacheItem> CacheItem::shared_from_this()
69	{
70	    return std::dynamic_pointer_cast<CacheItem>(Object::shared_from_this());
71	}
72	
73	std::shared_ptr<const CacheItem> CacheItem::shared_from_this() const
74	{
75	    return std::dynamic_pointer_cast<const CacheItem>(Object::shared_from_this());
76	}
