247	{
248	    std::vector<std::shared_ptr<CacheItem>> v;
249	    std::unique_lock                        lk(Impl::mtx);
250	    auto                                    itrange = pimpl->items.equal_range(&key);
251	
252	    for (auto it = itrange.first; it != itrange.second; ++it)
253	    {
254	        std::cerr << prefix << typeid(*(it->second)).name() << " - " << it->second.use_count() << std::endl;
255	    }
