259	std::shared_ptr<CacheItem> Cache::fetchOne(const IKey &key) const
260	{
261	    std::unique_lock lk(Impl::mtx);
262	
263	    auto [firstItem, lastItem] = pimpl->items.equal_range(&key);
264	
265	    for (auto it = firstItem; it != lastItem; ++it)
266	    {
267	        if (!it->second->isInUse())
268	        {
269	            return it->second;
270	        }
271	    }
272	
273	    return {};
274	}
